/**
 * Code themes (styles/code-themes.css, generated by scripts/gen-code-themes.mjs): every theme defines every variable, and
 * every text colour meets WCAG 1.4.3 (4.5:1) against the surface it sits on.
 */
import { readFileSync } from 'node:fs'
import { resolve } from 'node:path'
import { describe, expect, it } from 'vitest'
import { CODE_THEME_MODES, CODE_THEMES } from '../lib/code-themes'

const css = readFileSync(resolve(process.cwd(), 'src/styles/code-themes.css'), 'utf8')
const TEXT = ['fg', 'muted', 'keyword', 'string', 'number', 'comment', 'type', 'function', 'key', 'constant', 'punctuation', 'operator', 'tag', 'anchor'] as const
const TOKEN_TYPES = ['keyword', 'string', 'number', 'comment', 'type', 'function', 'key', 'constant', 'punctuation', 'operator', 'tag', 'anchor'] as const

function block(name: string): Record<string, string> {
  const m = new RegExp(`\\[data-code-theme="${name}"\\] \\{([^}]*)\\}`).exec(css)
  if (!m) return {}
  return Object.fromEntries([...m[1].matchAll(/--code-([a-z-]+):\s*(#[0-9a-f]{6});/g)].map((v) => [v[1], v[2]]))
}
const channel = (v: number) => (v <= 0.04045 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4)
const luminance = (hex: string) => {
  const [r, g, b] = [1, 3, 5].map((i) => channel(parseInt(hex.slice(i, i + 2), 16) / 255))
  return 0.2126 * r + 0.7152 * g + 0.0722 * b
}
const ratio = (a: string, b: string) => {
  const [x, y] = [luminance(a), luminance(b)].sort((p, q) => q - p)
  return (x + 0.05) / (y + 0.05)
}

describe('code themes', () => {
  it('lists the same themes in CSS and in CODE_THEMES, five dark and five light', () => {
    const inCss = [...css.matchAll(/^\[data-code-theme="([a-z]+)"\] \{/gm)].map((m) => m[1])
    expect(inCss).toEqual([...CODE_THEMES])
    expect(CODE_THEMES.filter((t) => CODE_THEME_MODES[t] === 'dark')).toHaveLength(5)
    expect(CODE_THEMES.filter((t) => CODE_THEME_MODES[t] === 'light')).toHaveLength(5)
  })

  it.each(CODE_THEMES)('%s: every text colour is at least 4.5:1 on its surface', (name) => {
    const v = block(name)
    expect(v.bg, `${name} --code-bg`).toMatch(/^#[0-9a-f]{6}$/)
    for (const key of TEXT) expect(ratio(v[key], v.bg), `${name} --code-${key} on --code-bg`).toBeGreaterThanOrEqual(4.5)
    expect(ratio(v['header-fg'], v.header), `${name} --code-header-fg on --code-header`).toBeGreaterThanOrEqual(4.5)
  })

  it.each(CODE_THEMES)('%s: dark themes are dark and light themes are light', (name) => {
    const bg = luminance(block(name).bg)
    if (CODE_THEME_MODES[name] === 'dark') expect(bg).toBeLessThan(0.1)
    else expect(bg).toBeGreaterThan(0.6)
  })

  it('colours every token type CodeViewer emits', () => {
    for (const type of TOKEN_TYPES) expect(css, type).toContain(`[data-type="${type}"] {\n  color: var(--code-${type});`)
  })

  it('loads nothing from the network and needs no font', () => {
    expect(css.replace(/\/\*[\s\S]*?\*\//g, '')).not.toMatch(/@import|url\(|@font-face/)
  })
})
